const host=(ctx)=>{const C=ctx.admin?.resolveHostPage?.('payments.admin');const p={path:'payments',label:'Платежи',group:'Коммерция',permission:'commerce.manage',hostPageKey:'payments.admin',...(C?{Component:C}:{})};ctx.admin?.registerNavItem?.({group:'Коммерция',path:'/admin/payments',label:'Платежи',permission:'commerce.manage',icon:'credit-card'});ctx.admin?.registerPage?.(p)};export const JaseflyFrontendModule={slug:'payments',version:'1.0.0',sdkVersion:1,async register(ctx){host(ctx);for(const type of ['payment-checkout','payment-methods','seller-info','offer-document'])ctx.builder?.registerWidget?.({type,label:type,category:'commerce',stableType:true,Render:()=>null})},async unregister(){}};export default JaseflyFrontendModule;